CREATE   VIEW dbo.vw_subcategory_performance  AS  select category,sub_category,  sum(sales) as total_sales,  sum(profit) as total_profit,  round(  sum(profit)/nullif(sum(sales),0)*100.0,2) as profit_margin,  sum(quantity) as total_quantity,  round(  avg(discount)*100.0,2) as average_discount_ptc,  round(  max(discount)*100.0,2) as maximum_discount_ptc,  count(distinct order_id) as distinct_orders,  count(distinct customer_id) as distinct_customers,  count(*) as total_rows   from dbo.clean_superstore_orders  group by category,sub_category;      